func TestReminderText(t *testing.T) {
	got := reminderText([]string{"first problem", "second problem"}, nil)
	if got != "Not a valid verdict: first problem; second problem. Call submit_review." {
		t.Errorf("reminderText = %q", got)
	}
	got = reminderText([]string{"unread parts"}, []string{"p1", "p2"})
	want := "Not a valid verdict: unread parts. 2 pinned part(s) unread; call read_file on p1, p2 before a verdict."
	if got != want {
		t.Errorf("reminderText = %q", got)
	}
	var ids []string
	for _, id := range []string{"p1", "p2", "p3", "p4", "p5", "p6", "p7", "p8", "p9", "p10"} {
		ids = append(ids, id)
	}
	got = reminderText([]string{"unread parts"}, ids)
	if !strings.Contains(got, "10 pinned part(s)") || strings.Contains(got, "p9") || !strings.Contains(got, "p8") {
		t.Errorf("reminderText = %q", got)
	}
}

